import{_ as a,o as s,c as n,a6 as i}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Preguntas frecuentes","description":"","frontmatter":{"title":"Preguntas frecuentes","docId":"user.preferences.faq","translationKey":"user.preferences.faq","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"efa3a64ab4d688fd7650801112a8d3200f2d685b223735f39c9163dbf095e6c4","translationRevision":"610ece2ee9771f678092e33a419435a4760f693c58f0efd6159a7ae7e0b2f097","order":40},"headers":[],"relativePath":"es/user/preferences/faq.md","filePath":"es/user/preferences/faq.md","lastUpdated":1794611623000}'),o={name:"es/user/preferences/faq.md"};function t(r,e,c,d,l,u){return s(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="frequently-asked-questions" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Preguntas frecuentes {#frequently-asked-questions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Resuelve dudas habituales antes de modificar datos o credenciales. Necesitas la aplicación de escritorio para las comprobaciones; <a href="./../requirements.html">requisitos</a> describe los paquetes compatibles. Las funciones locales mencionadas están disponibles salvo que se indique una limitación experimental o dependiente de servicios.</p><h2 id="does-cloud-sign-in-connect-tiktok" tabindex="-1">¿Iniciar sesión en Cloud conecta TikTok? <a class="header-anchor" href="#does-cloud-sign-in-connect-tiktok" aria-label="Permalink to &quot;¿Iniciar sesión en Cloud conecta TikTok? {#does-cloud-sign-in-connect-tiktok}&quot;">​</a></h2><p>No. Abre <a href="./../live/connections.html">Connections</a>, elige un creador e inicia LIVE por separado. La identidad Cloud sirve a operaciones vinculadas a cuentas. La cookie de TikTok pertenece únicamente a su campo oculto de conexión.</p><h2 id="why-is-a-connected-feed-empty" tabindex="-1">¿Por qué está vacío un feed conectado? <a class="header-anchor" href="#why-is-a-connected-feed-empty" aria-label="Permalink to &quot;¿Por qué está vacío un feed conectado? {#why-is-a-connected-feed-empty}&quot;">​</a></h2><p>Una sala tranquila puede no generar eventos nuevos. Selecciona todos, borra la búsqueda, reanuda el desplazamiento y comprueba la conexión. Pausar la vista mantiene la recepción y las automatizaciones. Vaciar el feed no reinicia puntos ni estadísticas persistentes.</p><h2 id="are-statistics-only-for-this-session" tabindex="-1">¿Las estadísticas son solo de esta sesión? <a class="header-anchor" href="#are-statistics-only-for-this-session" aria-label="Permalink to &quot;¿Las estadísticas son solo de esta sesión? {#are-statistics-only-for-this-session}&quot;">​</a></h2><p>La <a href="./../points/statistics.html">página Analytics</a> actual consulta agregados persistentes del creador y período seleccionados. Amplía las fechas y actualiza para revisar historial registrado. No es una transcripción completa. Los saldos utilizan reglas distintas y pueden incluir ajustes manuales o de automatizaciones.</p><h2 id="where-are-templates-variables-and-rankings" tabindex="-1">¿Dónde están plantillas, variables y rankings? <a class="header-anchor" href="#where-are-templates-variables-and-rankings" aria-label="Permalink to &quot;¿Dónde están plantillas, variables y rankings? {#where-are-templates-variables-and-rankings}&quot;">​</a></h2><p>Las plantillas y perfiles están en <a href="./../automations/templates.html">Automations</a>; Explore de Plugins solicita plugins. Los valores de ejecución están en Variables de Automations. El espacio experimental de rankings conserva <code>#/rankings</code>, pero está oculto en la navegación y no se restaura al iniciar. Las tablas de puntos y paneles del feed siguen siendo vistas separadas.</p><h2 id="does-saving-synchronize-everything" tabindex="-1">¿Guardar sincroniza todo? <a class="header-anchor" href="#does-saving-synchronize-everything" aria-label="Permalink to &quot;¿Guardar sincroniza todo? {#does-saving-synchronize-everything}&quot;">​</a></h2><p>No. Changes de Eventos/Acciones compara una referencia local. Variables guarda localmente y ofrece operaciones revisadas separadas de envío/adopción/retirada cuando son compatibles. Los secretos se ocultan en comparaciones. Las superposiciones Cloud usan creación/revisión y biblioteca; esta versión no tiene un adaptador Changes compartido. Lee <a href="./../cloud/changes.html">Changes</a> antes de elegir dirección.</p><h2 id="are-tests-harmless-and-do-imports-run-immediately" tabindex="-1">¿Las pruebas son inocuas y las importaciones se ejecutan inmediatamente? <a class="header-anchor" href="#are-tests-harmless-and-do-imports-run-immediately" aria-label="Permalink to &quot;¿Las pruebas son inocuas y las importaciones se ejecutan inmediatamente? {#are-tests-harmless-and-do-imports-run-immediately}&quot;">​</a></h2><p>Las pruebas pueden producir efectos, incluidos audio, solicitudes de red y cambios de puntos. Comienza con <a href="./../automations/first-rule.html">core.log</a>. Las definiciones importadas permanecen desactivadas: revísalas y actívalas explícitamente. Instalar un plugin también exige configurar su servicio antes de utilizar sus acciones.</p><h2 id="expected-result-and-recovery" tabindex="-1">Resultado esperado y recuperación <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;Resultado esperado y recuperación {#expected-result-and-recovery}&quot;">​</a></h2><p>Estas comprobaciones deberían identificar la página responsable sin reiniciar datos. Las consultas automáticas de actualización son opcionales; la instalación es experimental y está desactivada en el flujo de publicación actual. La colaboración remota completa y la búsqueda por apodo en producción dependen del despliegue y la aceptación. Si persiste una duda, conserva <a href="./backups.html">copias</a> y reúne un <a href="./troubleshooting.html">informe de diagnóstico</a> con versión, hora y reproducción.</p>',17)])])}const m=a(o,[["render",t]]);export{h as __pageData,m as default};
